INSERT INTO task_events VALUES('38cff3c0-0b58-49d4-a11b-294c2070724f','57c69735-3ce7-449e-a7ac-89955132a8fe','role_architect','subtask_done','subtask',NULL,'{"key":"architecture","title":"Определить общий контракт архива для сервера, веба и iPhone","result":"Документированный API, модель архива, поведение дерева и текущего выполнения; проверить, что реализация сервера и веба назначена. Для iOS Codex предлагает archived_at, GET /tasks?archived=true&include_children=true, POST /tasks/:id/archive и /restore с ответом {task}, DELETE только архивной карточки. Зафиксировать совместимый контракт до реализации.","role":"architect","depends_on":[],"parallel_with":[]}','2026-10-08 05:11:50');
INSERT INTO task_events VALUES('ad5f039b-83fa-4298-a21f-69999958ffd1','57c69735-3ce7-449e-a7ac-89955132a8fe','role_architect','step_outcome','architecture',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"Общий контракт архива зафиксирован до реализации: модель (archived_at/archived_by + task_purge_log), 5 ручек API с разделением архивирования (создатель) и restore/purge (владелец), поведение дерева и очередей, миграция 107, контракт для Codex. Граф полный, роли добавлять не нужно.","subtask_id":"0a9d45de-d747-4bfb-b24d-98fcc7dc743d","slot_key":"architecture","role":null}','2026-10-08 05:11:50');
