INSERT INTO task_events VALUES('eb7a29ef-7340-4a0b-a2e6-f449e01b90c2','108f248c-1a91-4308-a39e-b97a8e66931e',NULL,'role_choice','machine_selected_role',NULL,'Роль «Лайф-тестировщик» подобрана по сути работы — Необходимо пройти полный сценарий ролей, проверить edge-кейсы (рестарты, дубли, отвалы) и подтвердить живую передачу результата..','2026-10-08 17:10:32');
