INSERT INTO task_events VALUES('14fa9805-38b2-4765-9f17-ef59ea8e4627','61043857-ccb3-4b9f-8a45-127aeac024e6','role_builder','step_outcome','approval',NULL,'{"outcome":"blocked","code":"unknown","label":"причина не распознана","message":"Границы карточки исключают finishPlanIfComplete (planSubtaskAdmission) — корень инцидента. Без правки этой функции минимальный фикс невозможен. Также нужен дизайн нового видимого типа уведомления. Создан документ docs/current/coordination-owner-approval.md и коммит 0ae99b90 с диагнозом и ограничениями. Жду от владельца: расширить границы или согласовать дизайн нотификации.","subtask_id":"6180c547-7cbc-41a9-885b-396c3a00a0ae","slot_key":"approval","role":"builder"}','2026-10-09 00:48:31');
INSERT INTO task_events VALUES('18c040c8-1e7b-4190-9c5c-c19b4d1e1e60','61043857-ccb3-4b9f-8a45-127aeac024e6','role_builder','blocked_without_help_call','help',NULL,'В текущем составе темы (только @builder, слот approval) нет архитектора или дизайнера. Консультация (opus) использована. Для минимального фикса нужно решение владельца: расширить границы (разрешить править planSubtaskAdmission.finishPlanIfComplete) или согласовать дизайн нового видимого уведомления иным путём.','2026-10-09 00:48:31');
