INSERT INTO task_events VALUES('3e9fe1c9-b473-4f43-94a1-05b26e963b19','8aa62aea-8522-4400-af10-73a01b0a6ce0','role_architect','subtask_done','subtask',NULL,'Проверить актуальный сервер/web и existing submission_receipt: primary authority, timestamp/artifact/document, блокировку сдачи на QA-копии и ошибке, передачу следующей роли. Сопоставить с критериями карточки. Документ проекта с точными ревизиями/файлами, уже выполненным и оставшимся, предложением ролей и проверок для следующей итерации. Read-only: без правок, выкладки, production mutations, живых задач ради теста. iOS-код не менять; при обнаружении iOS-остатка описать отдельно.','2026-10-09 14:36:37');
