INSERT INTO task_events VALUES('a0f432a5-8f6a-4dbc-8f91-e72c76bcd516','8aa62aea-8522-4400-af10-73a01b0a6ce0','role_architect','subtask_done','subtask',NULL,'Доработка 2: Доработка 1: Проверить актуальный сервер/web и existing submission_receipt: primary authority, timestamp/artifact/document, блокировку сдачи на QA-копии и ошибке, передачу следующей роли. Сопоставить с критериями карточки. Документ проекта с точными ревизиями/файлами, уже выполненным и оставшимся, предложением ролей и проверок для следующей итерации. Read-only: без правок, выкладки, production mutations, живых задач ради теста. iOS-код не менять; при обнаружении iOS-остатка описать отдельно.','2026-10-09 14:42:32');
INSERT INTO task_events VALUES('d8bb07b1-758f-4500-ab98-11d6e818a2b7','8aa62aea-8522-4400-af10-73a01b0a6ce0','role_architect','step_outcome','architect_fix_3b3b09de',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"Третья сверка submission_receipt на HEAD 70e3b1ee без новых правок: 7 из 8 критериев карточки закрыты, D1 (веб-UI квитанции) и D2 (iOS без живой проверки) сохраняются. Документ обновлён, владельцу один вопрос — выносить ли веб-UI в отдельную карточку.","subtask_id":"b2e8b47d-86e0-44fe-b8a2-d1f3ff9eeb9e","slot_key":"architect_fix_3b3b09de","role":null}','2026-10-09 14:42:32');
