INSERT INTO task_events VALUES('1e798d85-da9e-42e3-927e-5f520e18eaa5','57c69735-3ce7-449e-a7ac-89955132a8fe','role_qa','subtask_done','subtask',NULL,'Проверить фактическое закрытие прежнего блокера: TypeError CollaborationPlanPanel и 404 role-slots, архивирование через деталь; дерево родитель→ребёнок→внук, restore и исключение из очереди. Вход main с a48f9672 и документ 003717fa-1a57-4e9e-b8ec-6b2a45e7535a. Изолированная QA-копия/тестовые данные, без реальных карточек владельца и выкладки. Сдать отчёт с ревизией, сценарием, доказательствами и всеми оставшимися дефектами.','2026-10-09 14:50:13');
INSERT INTO task_events VALUES('fb9e5026-5cae-40f8-8124-2b1e94c46f05','57c69735-3ce7-449e-a7ac-89955132a8fe','role_qa','step_outcome','archive_recheck',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"Проверил живо на QA-копии из main (a48f9672): блокер P2 (TypeError CollaborationPlanPanel + 404 role-slots, архивирование через деталь) фактически закрыт; кнопка «Отправить задачу в архив» работает, parent атомарно архивирует всё дерево одной меткой, restore вернул всех с parent_id. Нашёл новый дефект P1: purge архивной карточки возвращает 500 на UNIQUE constraint в tf_realtime_dirty.","subtask_id":"7097cd9d-2ee0-4e2a-af1c-b2cbea79309e","slot_key":"archive_recheck","role":null}','2026-10-09 14:50:13');
