INSERT INTO task_events VALUES('799b11b8-07cd-4765-8270-bf788ee77c06','c3c0c199-23b5-4114-a8b1-3df8d0f6cb68','role_architect','subtask_done','subtask',NULL,'Исследовать существующий webhook/одноразовый receiver и возможности Mac Codex; подтвердить поддерживаемое постоянное пробуждение чата 01a120f9-1266-7331-a4ca-81f6da2a698b. Зафиксировать точный API подписок для iOS: поля, CRUD/test, список событий, диагностика доставки и подтверждение wake. Документ проекта и рабочий минимальный прототип на изолированных событиях. Codex control socket сейчас отсутствует; не выдавать вывод HTTP за wake. Если нет поддерживаемого пути, эскалировать оркестратору точную причину, не бесконечные rework.','2026-10-09 15:07:57');
