INSERT INTO task_events VALUES('ccb3af1d-6fbc-46e9-b995-2e1a5fe98589','8aa62aea-8522-4400-af10-73a01b0a6ce0','role_builder','subtask_done','subtask',NULL,'Реализовать отсутствующий web-UI submission_receipt в карточке этапа (TaskDetailScreen/SubtaskFeed или фактический экран): подтверждённость primary, время, артефакт/документ, открытие отчёта. Использовать существующий серверный контракт, не дублировать готовую серверную часть. Отличать сообщения агента и серверную квитанцию, QA source/ошибка не становятся подтверждённой сдачей. Коммит/документ/доказательства. Собственный worktree, dirty main и production не трогать, без выкладки. Прочитать отчёты receipt_remaining. iOS не менять.','2026-10-09 15:18:53');
INSERT INTO task_events VALUES('3552d496-49e3-4a61-af4b-4b4f504d1f7a','8aa62aea-8522-4400-af10-73a01b0a6ce0','role_builder','step_outcome','receipt_web',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"В веб-карточке этапа теперь виден серверный submission_receipt: зелёный бейдж «Сдача подтверждена сервером» с временем UTC и ссылкой на отчёт под раскрытым результатом шага. Использован существующий эндпоинт без правок iOS и сервера. Коммит 2c14aa8e на ветке; vitest 179/179; tsc без новых ошибок.","subtask_id":"9f5e0136-9a9c-4ff4-a762-822ba472bbcb","slot_key":"receipt_web","role":null}','2026-10-09 15:18:53');
