INSERT INTO task_events VALUES('cfd6b1cc-e7b8-453c-9920-f656d0d33dbb','57c69735-3ce7-449e-a7ac-89955132a8fe','role_qa','subtask_done','subtask',NULL,'Повторная проверка после доработки: Доработка 1: Проверить фактическое закрытие прежнего блокера: TypeError CollaborationPlanPanel и 404 role-slots, архивирование через деталь; дерево родитель→ребёнок→внук, restore и исключение из очереди. Вход main с a48f9672 и документ 003717fa-1a57-4e9e-b8ec-6b2a45e7535a. Изолированная QA-копия/тестовые данные, без реальных карточек владельца и выкладки. Сдать отчёт с ревизией, сценарием, доказательствами и всеми оставшимися дефектами.','2026-10-09 15:39:19');
INSERT INTO task_events VALUES('ba55bdbc-93c0-46ee-9995-b20d3eeb7b3c','57c69735-3ce7-449e-a7ac-89955132a8fe','role_qa','step_outcome','qa_recheck_2',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"Блокер P0 (500 на UNIQUE tf_realtime_dirty при DELETE архивного grandchild с планом) закрыт в main@ce6ae51e: 21/21 серверных тестов зелёные, живой archive→purge→restore прошёл. Прежний блокер P2 закрыт в main, но **жив в рабочей ветке roles/57c69735-…** — она не содержит a48f9672. Архитектору при интеграции влить a48f9672 до переноса.","subtask_id":"6b15909d-edba-4464-a120-9a1f4d1b12de","slot_key":"qa_recheck_2","role":null}','2026-10-09 15:39:19');
