INSERT INTO task_events VALUES('60b572aa-d977-495f-93ec-ecd9946aa9aa','ebc4d338-86f1-4997-bc91-7e4a212cdf6f','role_qa','subtask_done','subtask',NULL,'Независимая проверка новой ревизии через реальный маршрут доставки/рестарт на изолированной БД: pending/picked, повтор HTTP, ошибка, смена поколения. Сверить с отчётом 04c20daf. Адресные дефекты, helper-тестов недостаточно.','2026-10-09 16:25:05');
INSERT INTO task_events VALUES('33f7e053-eaa0-4207-bcde-dd5de4256512','ebc4d338-86f1-4997-bc91-7e4a212cdf6f','role_qa','step_outcome','queue_repair_qa',NULL,'{"outcome":"submitted","code":null,"label":null,"message":"Принято с явными ограничениями. На ревизии a93345a8 (поверх ec822385+971e7490) проверил живо через реальный HTTP на изолированной БД: 4 критерия приёмки (двойное сообщение, повтор HTTP, fence-cold /new-session, рестарт до обработки) — все закрыты; E2E recovery-sweep и hot-fence в копии QA воспроизвести нельзя (sandbox=1 — by design), подтверждены по коду и тестам. Блокирующих дефектов нет.","subtask_id":"7e4a48d4-452a-41df-9ae2-b462fbf304d3","slot_key":"queue_repair_qa","role":null}','2026-10-09 16:25:05');
