INSERT INTO task_events VALUES('2b65c212-0b10-49cb-a388-0f9ca0ad15fd','905db3e3-74b9-4762-a222-0d84750936d3','role_qa','subtask_done','subtask',NULL,'Независимо проверить реальный API и доставку/receiver на изолированной БД после restart, повторов, сбоев; HMAC с исходным ключом, ответы без secret, реальные fixtures для native, shell quoting, HTTP≠queued≠confirmed. Не доверять helper-only тестам и комментариям. Полный event→receiver→новый чат согласовать с ведущим; не трогать живые карточки и не перезапускать прод. Вернуть адресные дефекты разработчику.','2026-10-10 20:56:37');
